function renderReviewQueue(sourceIndex) {
  return REVIEW_DEFINITIONS.map(item => ({
    review_id: item.review_id,
    priority: item.priority,
    status: 'open',
    question_ids: item.question_ids,
    source_record_ids: sourceIdsFor(item.refs.map(ref => ({ ref })), sourceIndex),
    review_action: item.review_action,
    reason: item.reason,
    blocking_if_unresolved: item.blocking_if_unresolved,
    evidence_references: evidenceForRefs(item.refs, sourceIndex)
  }));
}

function countBy(items, keyFn) {
  const counts = {};
  for (const item of items) {
    const key = keyFn(item);
    counts[key] = (counts[key] ?? 0) + 1;
  }
  return counts;
}

function normalizeQuestion(text) {
  return text.toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
}

function tokenSimilarity(left, right) {
  const a = new Set(normalizeQuestion(left).split(' '));
  const b = new Set(normalizeQuestion(right).split(' '));
  const intersection = [...a].filter(item => b.has(item)).length;
  const union = new Set([...a, ...b]).size;
  return union === 0 ? 0 : intersection / union;
}

function requiredSeedCoverage(questions) {
  const seeds = [
    ['financial_and_utilization_pa', /hospital financial and utilization data for pennsylvania/i],
    ['rural_hospital_closures', /public datasets could i use to study rural hospital closures/i],
    ['ownership_changes', /how could i study hospital ownership changes/i],
    ['nonprofit_health_system_finance', /financial condition of nonprofit health systems/i],
    ['county_capacity', /county is losing healthcare capacity/i],
    ['quality_workforce_utilization', /hospital quality, workforce, and utilization/i],
    ['facility_not_county', /facility-level rather than county-level/i],
    ['distress_across_states', /compare hospital financial distress across/i],
    ['maternity_deserts', /identify maternity-care deserts/i],
    ['mergers_or_ownership', /hospital mergers or changes of ownership/i],
    ['safety_net_dependence', /safety-net hospital dependence/i],
    ['prices_utilization', /relationship between hospital prices and utilization/i],
    ['construction_capital', /healthcare construction and capital investment/i],
    ['insurer_all_payer', /insurer or all-payer claims information/i],
    ['no_account_or_application', /without creating an account or applying for access/i]
  ];
  return Object.fromEntries(seeds.map(([id, pattern]) => [id, { matched: questions.some(question => pattern.test(question.natural_language_question)), pattern: String(pattern) }]));
}

function buildStatistics(questions, features, relevance, negatives, bundles, reviewQueue) {
  const featureKeys = ['conjunctions', 'exclusions', 'alternatives', 'grain_constraints', 'time_constraints', 'geography_constraints', 'access_constraints', 'source_authority_constraints', 'negative_requirements', 'multi_hop_requirements', 'ambiguous_language', 'unsupported_precision', 'near_miss_source_trap', 'stale_source_trap', 'public_metadata_private_data_trap', 'registry_versus_custody_trap'];
  const featureCoverage = Object.fromEntries(featureKeys.map(key => [key, features.filter(feature => feature.constraint_features[key]).length]));
  const sourceUsage = countBy([...relevance, ...negatives], judgment => judgment.source_record_id);
  const allTraps = countBy(questions.flatMap(question => question.trap_types), item => item);
  const allDimensions = countBy(questions.flatMap(question => question.benchmark_difficulty.dimensions), item => item);
  const bundleStatuses = countBy(bundles, bundle => bundle.join_status);
  return {
    statistics_version: 'question-to-data-statistics.v1',
    generated_at: FIXED_TIME,
    external_requests: 0,
    question_count: questions.length,
    question_composition: countBy(questions, question => question.geographic_composition),
    response_type_composition: countBy(questions, question => question.expected_response_type),
    split_counts: countBy(questions, question => question.split),
    split_geography_counts: countBy(questions, question => `${question.split}|${question.geographic_composition}`),
    judgment_counts: { positive: relevance.length, negative: negatives.length, by_label: { ...countBy(relevance, item => item.label), ...Object.fromEntries(Object.entries(countBy(negatives, item => item.label)).map(([key, value]) => [`negative:${key}`, value])) }, sources_judged: sourceUsage },
    bundle_counts: { records: bundles.length, multi_source_questions: questions.filter(question => question.expected_response_type === 'multi_source_bundle').length, by_join_status: bundleStatuses, join_proven: bundles.filter(bundle => bundle.join_status === 'join_proven').length, actual_join_proven: bundles.filter(bundle => bundle.actual_join_proven).length },
    difficulty_profile: { by_level: countBy(questions, question => question.benchmark_difficulty.level), by_dimension: allDimensions, by_trap_type: allTraps },
    feature_coverage: featureCoverage,
    seed_coverage: requiredSeedCoverage(questions),
    human_review_count: reviewQueue.length,
    prohibited_action_attestation: { retrieval_engine_implemented: false, network_requests_made: 0, acquisition_executed: false, identity_merge_performed: false, full_data_job_executed: false, heavy_analysis_lock_acquired: false, statement: 'This package is an offline benchmark and gold-plan artifact only.' }
  };
}

function designReport(statistics, sourceIndex) {
  const geoLines = Object.entries(statistics.question_composition).map(([key, value]) => `| ${key} | ${value} |`).join('\n');
  const typeLines = Object.entries(statistics.response_type_composition).map(([key, value]) => `| ${key} | ${value} |`).join('\n');
  const trapLines = Object.entries(statistics.difficulty_profile.by_trap_type).sort((a, b) => b[1] - a[1]).slice(0, 12).map(([key, value]) => `| ${key} | ${value} |`).join('\n');
  return `# Lane O3 — Question-to-Data Discovery Benchmark v0.1.0

## Status and control preamble

This is an offline benchmark and gold-plan package for the United States Health Systems Observatory product layer. External requests: **0**. It does not implement retrieval, acquisition, identity resolution, source downloading, or full-data analysis.

The shared product-layer controls applied here are: existing project records are the only source universe; source edits make benchmark evidence stale; catalog metadata is not proof of source-data custody or current accessibility; access, unresolved identity, stale freshness, and unavailable states remain typed; no identity merge is created; and no bundle receives join_proven without existing project proof. The package records evidence references rather than copying or rewriting the source records.

## Population and composition

Exactly 60 questions are included. Each question has a unique topic cluster and is assigned deterministically to development, validation, or held-out test. No near-identical paraphrase cluster is split across partitions.

| Geographic composition | Questions |
| --- | ---: |
${geoLines}

| Expected response type | Questions |
| --- | ---: |
${typeLines}

The response types are gold behavior labels, not retrieval-engine outputs: single-source recommendation, coherent multi-source bundle, clarification before ranking, or explicit unsupported/incomplete abstention.

## Evidence boundary

The package references ${Object.keys(sourceIndex).length} existing project records: source-registry entries from ${REGISTRY_PATH} and asset-granular records from the Observatory rural-closure fixture. Registry entries retain their project status (including catalog_metadata_only, partial, special_access, and uncovered). Fixture records retain their explicit evidence, access, freshness, and candidate-join states.

Every positive and negative judgment carries source-record/family IDs, exact project-artifact locators, analytical grain/time/geography, access implications, and limitations. Negative judgments are not claims of corpus-wide absence; they are scoped reasons not to recommend a particular existing record for a particular question.

## Bundle design

Each multi-source question has required analytical roles, a minimum viable bundle, optional enrichment, join fields, crosswalk requirements, grain/geography/time/access compatibility, known gaps, and conditions that prevent recommendation. The package contains no join_proven bundle. Candidate joins remain candidate/crosswalk/incompatible/unknown according to the existing evidence boundary.

## Difficulty profile

The corpus covers conjunctions, exclusions, API/download alternatives, facility-versus-county grain, annual time windows, Pennsylvania scope, anonymous access, original-government authority, negative requirements, multi-hop closure/impact questions, ambiguous capacity/distress language, unsupported daily profitability precision, near misses, stale-source risk, public-metadata/private-data traps, and registry-versus-custody traps.

| Trap type | Questions |
| --- | ---: |
${trapLines}

## Evaluation

The metric specification defines retrieval ranking metrics (Recall@1/@3/@5/@10, Precision@k, MRR, nDCG@k, essential-source recall, near-miss rejection), constraint handling, bundle quality, explanation/trust, and clarification/abstention measures. No system scores are reported in v0.1.0; evaluation is specification-only.

## Review and known gaps

The open human-review queue covers current endpoint/field verification, PHC4 and state-product access, IRS entity/perimeter semantics, CMS ownership event semantics, cross-state comparability, maternity-care support, capital-project coverage, and deliberate unsupported precision/claims/ownership cases. These items do not weaken the gold labels; they identify where the current index cannot responsibly support a stronger claim.

## Validation and prohibited actions

The validator is fixture-first and local-only. It checks exact counts, partition reconciliation, evidence-file existence, source-record existence, judgment completeness, bundle coherence, access-sensitive negatives, deterministic split leakage controls, manifest hashes, and prohibited-action flags. No external requests, live source refresh, heavy-analysis lock, identity merge, full-data job, or retrieval engine was used.
`;
}

async function listPackageFiles() {
  const output = [];
  async function visit(directory, prefix = '') {
    const entries = await fs.readdir(directory, { withFileTypes: true });
    for (const entry of entries.sort((a, b) => a.name.localeCompare(b.name))) {
      if (entry.name === 'node_modules' || entry.name.endsWith('.partial')) continue;
      const relative = prefix ? `${prefix}/${entry.name}` : entry.name;
      const absolute = path.join(directory, entry.name);
      if (entry.isDirectory()) await visit(absolute, relative);
      else if (entry.isFile() && !['package_manifest.json', 'validation_report.json'].includes(relative)) output.push(relative);
    }
  }
  await visit(PACKAGE_ROOT);
  return output.sort();
}

async function buildPackageManifest(sourceIndex) {
  const files = await listPackageFiles();
  const fileEntries = [];
  for (const relative of files) {
    const bytes = await fs.readFile(path.join(PACKAGE_ROOT, relative));
    fileEntries.push({ path: relative, bytes: bytes.byteLength, sha256: crypto.createHash('sha256').update(bytes).digest('hex') });
  }
  const sourcePinPaths = [
    { path: REGISTRY_PATH, role: 'source registry containing financial/ownership/access records' },
    { path: ACQUISITION_PATH, role: 'source acquisition/access evidence matrix' },
    { path: SNAPSHOT_VALIDATION_PATH, role: 'controlling offline project-state validation pin' },
    { path: FIXTURE_MANIFEST_PATH, role: 'Observatory fixture manifest' },
    ...Object.values(FIXTURE_REFS).map(item => ({ path: item.path, role: `existing Observatory record ${item.recordId}` }))
  ];
  const source_pins = [];
  for (const pin of uniqueBy(sourcePinPaths, item => item.path)) {
    const digest = await hashFile(pin.path);
    source_pins.push({ artifact_path: pin.path, role: pin.role, bytes: digest.bytes, sha256: digest.sha256 });
  }
  return {
    $schema: './schemas/package-manifest.schema.json',
    manifest_version: 'question-to-data-package-manifest.v1',
    package_id: 'ushso-question-to-data-v0.1.0',
    package_version: '0.1.0',
    created_at: FIXED_TIME,
    offline: true,
    external_requests: 0,
    identity_merge_performed: false,
    retrieval_engine_implemented: false,
    manifest_excludes: ['package_manifest.json', 'validation_report.json'],
    source_pins,
    source_reference_count: Object.keys(sourceIndex).length,
    file_count: fileEntries.length,
    payload_bytes: fileEntries.reduce((sum, item) => sum + item.bytes, 0),
    files: fileEntries,
    immutable: true
  };
}

async function writeFixtures(questions, relevance, negatives, bundles, plans) {
  await writeJson('fixtures/valid/question.valid.json', questions[0]);
  await writeJson('fixtures/valid/relevance-judgment.valid.json', relevance[0]);
  await writeJson('fixtures/valid/bundle-gold.valid.json', bundles[0]);
  await writeJson('fixtures/valid/answer-plan.valid.json', plans[0]);
  const missingAccess = { ...questions[0] };
  delete missingAccess.required_access;
  await writeJson('fixtures/invalid/question.missing-access.json', missingAccess);
  await writeJson('fixtures/invalid/relevance.no-evidence.json', { ...relevance[0], evidence_references: [] });
  await writeJson('fixtures/invalid/bundle.unknown-join-status.json', { ...bundles[0], join_status: 'join_fabricated' });
  await writeJson('fixtures/invalid/answer-plan.confident-unsupported.json', { ...plans.find(plan => plan.recommendation.mode === 'unsupported_or_incomplete'), recommendation: { mode: 'single_source', decision: 'recommend_with_constraints', source_record_ids: ['fake'], candidate_source_record_ids: [], bundle_id: null } });
  await writeJson('fixtures/invalid/negative.recommended.json', { ...negatives[0], recommendation_allowed: true });
}

export async function buildBenchmark() {
  if (SPECS.length !== 60) throw new Error(`Expected 60 authored specs, found ${SPECS.length}`);
  const refs = uniqueStrings(SPECS.flatMap(allSourceRefs));
  const sourceIndex = await loadSourceIndex(refs);
  const questions = SPECS.map(spec => renderQuestion(spec, sourceIndex));
  const features = SPECS.map(renderQuestionFeatures);
  const relevance = SPECS.flatMap(spec => spec.positive_sources.map((plan, index) => renderPositiveJudgment(spec, plan, index, sourceIndex)));
  const negatives = SPECS.flatMap(spec => spec.negative_sources.map((plan, index) => renderNegativeJudgment(spec, plan, index, sourceIndex)));
  const bundles = SPECS.filter(spec => spec.expected_response_type === 'multi_source_bundle').map(spec => renderBundle(spec, sourceIndex));
  const plans = SPECS.map(spec => renderAnswerPlan(spec, sourceIndex, bundles.find(bundle => bundle.question_id === spec.id)));
  const reviewQueue = renderReviewQueue(sourceIndex);
  const statistics = buildStatistics(questions, features, relevance, negatives, bundles, reviewQueue);
  const splitIds = Object.fromEntries(EXPECTED_SPLITS.map(split => [split, questions.filter(question => question.split === split).map(question => question.question_id)]));
  const crossSplitSimilarity = [];
  for (let i = 0; i < questions.length; i += 1) {
    for (let j = i + 1; j < questions.length; j += 1) {
      if (questions[i].split !== questions[j].split) {
        const similarity = tokenSimilarity(questions[i].natural_language_question, questions[j].natural_language_question);
        if (similarity >= 0.72) crossSplitSimilarity.push({ left: questions[i].question_id, right: questions[j].question_id, similarity: Number(similarity.toFixed(4)) });
      }
    }
  }
  const splitArtifact = { splits_version: 'question-to-data-splits.v1', algorithm: 'Explicit 20/20/20 assignment with four questions from each geographic composition per split; stable question IDs; no randomization.', seed: 'QTD-O3-v0.1.0-fixed', external_requests: 0, splits: splitIds, counts: Object.fromEntries(Object.entries(splitIds).map(([key, value]) => [key, value.length])), leakage_controls: { unique_topic_clusters: SPECS.length, cross_split_near_duplicate_threshold: 0.72, cross_split_near_duplicate_pairs: crossSplitSimilarity, same_topic_cluster_across_splits: [], statement: 'Each question has a unique topic_cluster; no near-identical paraphrase is assigned across splits.' } };
  const sourceReferenceIndex = { $schema: './schemas/source-reference-index.schema.json', index_version: 'question-to-data-source-reference.v1', generated_at: FIXED_TIME, external_requests: 0, source_reference_count: Object.keys(sourceIndex).length, sources: Object.values(sourceIndex).sort((a, b) => a.source_record_id.localeCompare(b.source_record_id)) };
  const designReportText = designReport(statistics, sourceIndex);

  for (const [filename, schema] of Object.entries(SCHEMAS)) await writeJson(`schemas/${filename}`, schema);
  await writeJsonl('questions.jsonl', questions);
  await writeJsonl('question_features.jsonl', features);
  await writeJsonl('relevance_judgments.jsonl', relevance);
  await writeJsonl('negative_judgments.jsonl', negatives);
  await writeJsonl('bundle_gold.jsonl', bundles);
  await writeJsonl('answer_plans.jsonl', plans);
  await writeJsonl('human_review_queue.jsonl', reviewQueue);
  await writeJson('evaluation_metrics.json', EVALUATION_METRICS);
  await writeJson('benchmark_splits.json', splitArtifact);
  await writeJson('benchmark_statistics.json', statistics);
  await writeJson('source_reference_index.json', sourceReferenceIndex);
  await writeAtomic('benchmark_design_report.md', designReportText);
  await writeFixtures(questions, relevance, negatives, bundles, plans);
  await writeAtomic('README.md', `# USHSO Question-to-Data Discovery Benchmark v0.1.0\n\nThis is the offline Lane O3 benchmark package. Run npm test for fixture-first tests and npm run validate for package validation. Build is deterministic and reads only existing local project metadata/evidence records.\n\nThe package contains exactly 60 structured questions, source-bound relevance judgments, coherent bundle goldens, answer plans, deterministic splits, metric definitions, review items, schemas, valid/invalid fixtures, a design report, a manifest, and a validation report. It does not implement retrieval or perform external requests.\n`);

  const manifest = await buildPackageManifest(sourceIndex);
  await writeJson('package_manifest.json', manifest);
  const { runValidation } = await import('./validate_benchmark.mjs');
  const validation = await runValidation({ writeReport: true });
  if (!validation.ok) throw new Error(`Generated benchmark failed validation: ${validation.issues.join('; ')}`);
  return { statistics, manifest, validation };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  buildBenchmark().then(result => process.stdout.write(`${JSON.stringify({ ok: true, questions: result.statistics.question_count, external_requests: 0 }, null, 2)}\n`)).catch(error => { process.stderr.write(`${error.stack ?? error}\n`); process.exitCode = 1; });
}
